ata-processed="true"><div class="GlO4G" data-processed="true">gdscript</div></div><div class="PGvq2d" dir="ltr" data-processed="true"><pre data-processed="true"><code jsuid="vtZBl_13u" data-processed="true"><span class="undefined" data-processed="true">shader_type canvas_item;

uniform sampler2D SCREEN_TEXTURE : hint_screen_texture, filter_nearest;
uniform int dither_size : hint_range(1, 4) = 2;
uniform float contrast_amount : hint_range(1.0, 3.0) = 1.5;

